import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.LinkedList;import java.util.Queue;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());ArrayList<ArrayList<Integer>> adj = new ArrayList<ArrayList<Integer>>(n + 1);for (int i = 0; i <= n; i++) {adj.add(new ArrayList<Integer>());}for (int i = 0; i < m; i++) {st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj.get(u).add(v);adj.get(v).add(u);}System.out.println(bfs(n, adj));}}private static int bfs(int n, ArrayList<ArrayList<Integer>> adj) {int[] dist = new int[n + 1];for (int i = 0; i <= n; i++) dist[i] = -1;Queue<Integer> q = new LinkedList<Integer>();q.add(1);dist[1] = 0;while (!q.isEmpty()) {int curr = q.poll();if (curr == n) return dist[curr];for (int neighbor : adj.get(curr)) {if (dist[neighbor] == -1) {dist[neighbor] = dist[curr] + 1;q.add(neighbor);}}}return -1;}}